import 'package:flutter/material.dart';import 'package:provider/provider.dart';import '../../providers/app_provider.dart';
class EditProfileScreen extends StatefulWidget{const EditProfileScreen({super.key});@override State<EditProfileScreen> createState()=>_EditProfileScreenState();}
class _EditProfileScreenState extends State<EditProfileScreen>{late TextEditingController name,email,phone;@override void initState(){super.initState();final u=context.read<AppProvider>().user;name=TextEditingController(text:u?.fullName??'');email=TextEditingController(text:u?.email??'');phone=TextEditingController(text:u?.phone??'');}@override void dispose(){name.dispose();email.dispose();phone.dispose();super.dispose();}void save(){final app=context.read<AppProvider>(),u=app.user;if(u==null)return;app.updateUser(u.copyWith(fullName:name.text.trim().isEmpty?u.fullName:name.text.trim(),email:email.text.trim().isEmpty?null:email.text.trim(),phone:phone.text.trim()));Navigator.pop(context);ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Profile updated successfully.')));}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Edit Profile')),body:ListView(padding:const EdgeInsets.all(20),children:[TextField(controller:name,decoration:const InputDecoration(labelText:'Full name',prefixIcon:Icon(Icons.person_outline))),const SizedBox(height:14),TextField(controller:phone,keyboardType:TextInputType.phone,decoration:const InputDecoration(labelText:'Phone number',prefixIcon:Icon(Icons.phone))),const SizedBox(height:14),TextField(controller:email,keyboardType:TextInputType.emailAddress,decoration:const InputDecoration(labelText:'Email',prefixIcon:Icon(Icons.email_outlined))),const SizedBox(height:26),ElevatedButton.icon(onPressed:save,icon:const Icon(Icons.save),label:const Text('Save Changes'))]));}
